WITH src AS (SELECT * FROM stores WHERE region IN ('North', 'South', 'East') AND sqft <= 5427), sqft_bucket_summary AS (SELECT CASE WHEN sqft >= 13514 THEN 'high' WHEN sqft >= 6995 THEN 'mid' ELSE 'low' END AS sqft_bucket, SORT_ARRAY(COLLECT_SET(city)) AS city_list FROM src GROUP BY CASE WHEN sqft >= 13514 THEN 'high' WHEN sqft >= 6995 THEN 'mid' ELSE 'low' END) SELECT * FROM sqft_bucket_summary ORDER BY sqft_bucket;
